const FIGMA='https://www.figma.com/design/orHtJZjo43kf32eF41krSU/Portfolio-Paul-Balcon?node-id=11-2082&t=unMKWeNjN2ZJHn2e-1';
const PROJECTS={
melo:{name:'MELO',number:'01',tone:'melo',discipline:'Product design · Expérience étudiante',headline:'Un petit rendez-vous.<br>Un peu plus de <em>bien-être.</em>',intro:'Une application de santé mentale pensée autour du quotidien étudiant, avec une expérience mobile et un espace pour les établissements.',meta:[['Format','Application & dashboard'],['Univers','Santé mentale étudiante'],['Approche','Produit & UX/UI'],['Statut','Projet de conception']],context:'Comment faire une place au bien-être dans une journée d’étudiant ?',description:'MELO réunit un suivi de l’humeur, du lien humain et des ressources dans une même expérience. Le projet articule deux points de vue : celui de l’étudiant dans son quotidien, et celui de l’établissement qui accompagne ses promotions.',focus:[['Un moment pour soi','Le check-in quotidien est le point d’entrée de l’expérience : prendre un instant pour exprimer son humeur.'],['Un lien vers les autres','Le buddy system et la communauté donnent une place aux échanges entre étudiants.'],['Des ressources accessibles','Des contenus de bien-être et un chatbot contextualisé à l’université complètent l’accompagnement.']],steps:[['Exprimer','Faire le point sur son humeur dans un check-in quotidien.'],['Échanger','Retrouver son buddy ou rejoindre la communauté.'],['Explorer','Accéder aux ressources et au chatbot contextualisé.']],deliverables:['Application mobile','Check-in d’humeur gamifié','Buddy system & communauté','Dashboard établissement'],outcome:'Une vision produit à deux échelles.',outcomeText:'Le mobile rassemble les usages du quotidien. Le tableau de bord établissement prévoit des alertes, une visualisation par promotion et une file de priorité pour les conseillers. Ce portfolio présente le concept, sans revendiquer de résultats cliniques ou de déploiement.',resourceNote:'Les écrans Figma propres à MELO et les résultats de tests ne sont pas encore joints à cette étude.',quote:'Créer une porte d’entrée simple vers le bien-être.',axis:'Une expérience, deux perspectives.',axisItems:[['Côté étudiant','Humeur · Linda · Buddy · Ressources'],['Côté établissement','Alertes · Promotions · Accompagnement']]},
pikit:{figmaUrl:'https://www.figma.com/design/4tqIJoENMIJZpqVhZMUf8Q/PIK-IT?node-id=1357-7610',name:'Pik-It',number:'02',tone:'pikit',discipline:'Product design · Pilotage de projet',headline:'Le monde devient<br>un <em>terrain de jeu.</em>',intro:'Un projet d’application mobile sociale qui transforme la collecte de photos en défis, pour contribuer à l’entraînement d’une IA spatiale.',meta:[['Format','Application mobile'],['Contribution','Design & pilotage'],['Outils','Figma · Design System'],['Démarche','Recherche → prototype → tests']],context:'Comment donner envie de contribuer, photo après photo ?',description:'Pik-It associe une contribution à la collecte de données visuelles à une expérience de jeu. Le projet mobilise autant la conception de parcours que la réflexion sur les motivations, la stratégie commerciale et la viabilité financière.',focus:[['Cadrer le produit','Idéation, étude de marché et réflexion sur les dimensions commerciales et financières.'],['Dessiner l’expérience','Empathy map, parcours utilisateur et wireframes pour structurer l’application avant le prototypage.'],['Donner envie de revenir','Une stratégie de gamification travaillant les motivations intrinsèques et extrinsèques, accompagnée de tests utilisateurs et d’itérations.']],steps:[['Explorer','Parcourir les défis et trouver une occasion de contribuer autour de soi.'],['Capturer','La photo devient le geste central de participation au jeu.'],['Se challenger','Les battles et les interactions sociales prolongent l’expérience.']],deliverables:['Étude de marché','Empathy map & parcours','Wireframes','Prototype Figma','Design System','Tests & itérations'],outcome:'Du besoin au prototype, une vision de bout en bout.',outcomeText:'Mon travail couvre l’idéation, l’étude de marché, les parcours, la maquette Figma et le Design System. Les tests utilisateurs et les retours alimentent les itérations produit. La réflexion commerciale et financière accompagne la conception.',resourceNote:'Explorez le fichier Pik-It dans l’aperçu, ou ouvrez-le dans Figma pour profiter de tous les outils de navigation.',quote:'Une même ambition : concevoir le produit et garder le cap du projet.',axis:'Deux regards sur le même produit.',axisItems:[['Product Designer','Empathie · Parcours · Prototype · Tests'],['Chef de projet digital','Cadrage · Pilotage · Stratégie · Itérations']]},
biodiv:{name:'BioDiv',number:'03',tone:'biodiv',discipline:'UX/UI · Identité visuelle',headline:'Penser l’interface<br>à travers <em>le vivant.</em>',intro:'Un projet UX/UI abordé chez Sense4Data, avec une direction visuelle inspirée de la nature.',meta:[['Contexte','Sense4Data'],['Période','Fév. — juil. 2024'],['Rôle','Product Designer'],['Domaine','UX/UI & identité']],context:'Relier le sujet, l’identité et l’expérience.',description:'BioDiv s’inscrit dans mon expérience de Product Designer chez Sense4Data. Mon stage m’a amené à travailler sur la compréhension du besoin client et sur des interfaces et prototypes mobiles et web. BioDiv explore une identité inspirée de la nature.',focus:[['Le contexte','Un projet abordé en environnement professionnel, au sein de Sense4Data.'],['Le champ de conception','Une contribution UX/UI et une réflexion sur la direction visuelle.'],['L’identité','Une palette et un univers inspirés du vivant pour porter le sujet.']],steps:[['Sujet','La nature comme point de départ de l’univers visuel.'],['Identité','Une direction graphique en lien avec le vivant.'],['Interface','La traduction de cet univers dans le travail UX/UI.']],deliverables:['Conception UX/UI','Direction visuelle','Exploration de palette'],outcome:'Une expérience de design en contexte professionnel.',outcomeText:'Cette étude présente le périmètre connu du projet. Les écrans livrés et le détail des arbitrages permettront de documenter précisément la réalisation. Aucun résultat chiffré n’est présenté sans source.',resourceNote:'Les livrables originaux de BioDiv et leurs liens de consultation restent à joindre.',quote:'Faire dialoguer une identité et les usages qu’elle accompagne.',axis:'Du sujet à l’expérience.',axisItems:[['Identité visuelle','Nature · Palette · Cohérence'],['Design d’interface','Compréhension · Structure · Lisibilité']]},
web:{name:'Tisseurs d’histoires',number:'04',tone:'web',discipline:'Web design · Développement Webflow',headline:'Une scène digitale<br>pour les <em>histoires.</em>',intro:'Un site pour une association de théâtre liée à la culture bretonne, réalisé pendant mon stage chez Catalpa.',meta:[['Client','Tisseurs d’histoires'],['Agence','Catalpa · Plouguerneau'],['Période','Juin — juillet 2025'],['Réalisation','Site vitrine · Webflow']],context:'Faire exister une association culturelle sur le web.',description:'Tisseurs d’histoires crée des pièces de théâtre liées à la culture bretonne. Le site internet fait partie des réalisations de mon stage de Web Developer chez Catalpa, agence de communication digitale à Plouguerneau.',focus:[['Une association','Un univers porté par le théâtre, les récits et la culture bretonne.'],['Un site vitrine','Un support numérique pour présenter l’association et son activité.'],['Une réalisation en agence','Un projet réalisé avec Webflow, dans le cadre d’un stage de deux mois chez Catalpa.']],steps:[['Découvrir','Présenter l’association et son univers culturel.'],['Comprendre','Mettre en perspective le théâtre et les histoires du territoire.'],['Rencontrer','Faire du site un point de contact avec l’association.']],deliverables:['Site vitrine','Conception web','Intégration Webflow'],outcome:'Du design à la réalisation web.',outcomeText:'Le site a été créé dans le cadre de mon expérience chez Catalpa. Cette mission s’inscrit aux côtés du site Manach Bois réalisé pendant le même stage. La couverture présente l’interface du site dans son identité visuelle originale.',resourceNote:'La couverture originale est consultable ci-dessous. Le lien du site sera ajouté lorsqu’il sera disponible.',quote:'Donner de la place aux voix, aux récits et à un territoire.',axis:'Un projet au croisement de deux pratiques.',axisItems:[['Web design','Contenus · Hiérarchie · Identité'],['Développement','Webflow · Intégration · Site vitrine']]}}
Object.assign(PROJECTS.melo,{"discipline": "UX/UI · Front-end · HEC AI Entrepreneurship", "intro": "MELO est né à HEC dans le cadre du certificat AI Entrepreneurship : six semaines pour lancer un projet de startup. Notre équipe a obtenu le certificat à l’issue de la présentation du projet devant un jury d’investisseurs.", "meta": [["Programme", "HEC · AI Entrepreneurship"], ["Durée", "6 semaines · Projet de startup"], ["Mon rôle", "UX/UI Design & Front-end"], ["Aboutissement", "Certificat obtenu · Jury d’investisseurs"]], "context": "Comment aider les universités à agir plus tôt ?", "description": "Nous avons développé MELO pendant les six semaines du certificat AI Entrepreneurship à HEC, avec pour objectif de lancer un projet de startup. Notre proposition associe une application étudiante et une plateforme pour les universités, afin de repérer les signaux de difficulté et faciliter un accompagnement plus précoce. Le pitch MELO part d’un constat : les enquêtes, la baisse des notes et les consultations spontanées donnent une visibilité partielle sur le bien-être étudiant. Le projet propose de relier les signaux du quotidien à une plateforme d’accompagnement, tout en créant une expérience que les étudiants ont envie de retrouver.", "focus": [["Mon rôle : UX/UI et front-end", "Au sein du groupe 14, mon rôle porte sur le design UX/UI et le front-end. L’expérience articule une interface étudiante engageante et une plateforme de lecture des signaux pour les établissements."], ["Un usage quotidien léger", "Le pitch prévoit un check-in d’humeur en moins de dix secondes, des points et des séries de participation. La mascotte reflète l’humeur et accompagne le parcours."], ["Une lecture utile aux équipes", "Le dashboard présenté regroupe alertes, détection de risques, analytics et rapports. Le projet prévoit aussi un contexte universitaire pour le chatbot."]], "steps": [["Exprimer", "Indiquer son humeur, puis préciser son ressenti et les facteurs associés."], ["Souffler", "Accéder à une proposition d’exercice de respiration guidée."], ["Revenir", "Terminer le moment de bien-être et retrouver son espace personnel."]], "deliverables": ["Application étudiante", "Interface de check-in", "Parcours de respiration", "Dashboard université", "Analytics & alertes", "Pitch deck & modèle économique"], "outcome": "Du projet de startup au jury d’investisseurs.", "outcomeText": "Au terme du programme, nous avons présenté MELO devant un jury d’investisseurs et obtenu le certificat AI Entrepreneurship de HEC. Ces six semaines nous ont permis de construire et défendre un projet de startup, de la proposition produit au modèle économique. Le pitch propose un modèle B2B2C financé par les universités. La première version prévoit un triage fondé sur des règles et plusieurs sources de signaux. Une étape ultérieure envisage un modèle prédictif entraîné sur plus de deux ans de données. Le modèle économique, les économies annoncées et la feuille de route sont des hypothèses de projet, pas des résultats d’exploitation.", "resourceNote": "Les écrans ci-dessous proviennent du pitch final fourni. Ils présentent le produit et son intention ; les données affichées ne constituent pas une validation clinique.", "quote": "Un produit. Deux plateformes. Une boucle de données.", "axis": "De l’expérience quotidienne à l’accompagnement.", "axisItems": [["Pour les étudiants", "Humeur · Respiration · Communauté · Ressources"], ["Pour les universités", "Alertes · Analytics · Rapports · Contexte chatbot"]], "coverCaption": "Écrans originaux présentés dans le pitch MELO · Page 9.", "links": [["Ouvrir l’application MELO", "Explorer la démonstration étudiante hébergée sur Base44.", "https://melo-student-app.base44.app", "external"], ["Télécharger le pitch MELO", "Présentation finale du projet · PDF · 37 pages.", "assets/melo-pitch-deck.pdf", "download"]], "gallery": [["assets/melo-09.webp", "L’application étudiante", "Pitch MELO · Page 9"], ["assets/melo-10.webp", "Le check-in d’humeur", "Pitch MELO · Page 10"], ["assets/melo-11.webp", "Un exercice de respiration", "Pitch MELO · Page 11"], ["assets/melo-12.webp", "La fin du parcours", "Pitch MELO · Page 12"], ["assets/melo-13.webp", "Le tableau de bord université", "Pitch MELO · Page 13"], ["assets/melo-14.webp", "Les alertes et la détection", "Pitch MELO · Page 14"], ["assets/melo-15.webp", "Les analytics et rapports", "Pitch MELO · Page 15"], ["assets/melo-16.webp", "Le contexte du chatbot", "Pitch MELO · Page 16"]], "projectFacts": [["Programme", "HEC", "Certificat AI Entrepreneurship"], ["Format", "6 semaines", "Pour lancer un projet de startup"], ["Aboutissement", "Certificat obtenu", "Présentation devant un jury d’investisseurs"]], "projectTeam": "Projet collectif · Aela Ribadeau Dumas, Irenne Oprescu, Paul Balcon, Alan Teurroc et Yokoyama Kazuhiro."});
PROJECTS.neotravel={"name": "NeoTravel", "number": "05", "tone": "neotravel", "discipline": "Projet digital · Automatisation · Expérience conversationnelle", "headline": "De la demande<br>au <em>devis.</em>", "intro": "Digitaliser la chaîne commerciale du transport de groupe, pour rendre du temps aux équipes et accélérer le traitement des demandes.", "meta": [["Contexte", "Équipe 23 · Campus Bordeaux"], ["Format", "Projet collectif · MVP"], ["Expérience", "Site & dashboard"], ["Périmètre", "Demande → qualification → devis"]], "context": "La demande existe. La capacité de traitement devient le frein.", "description": "Le cas NeoTravel décrit un intermédiaire en transport de groupe, sans flotte en propre. Les commerciaux qualifient les besoins et négocient, tandis que les agents de réservation coordonnent les partenaires. Selon la présentation, environ 60 leads arrivent chaque jour via Ads et SEO, pour un traitement manuel d’environ 45 minutes par lead.", "focus": [["Prioriser un MVP réalisable", "L’équipe a priorisé le moteur de devis, la qualification, la génération et l’envoi des devis, puis les relances. Les choix croisent impact commercial, besoin client, urgence et faisabilité sur une semaine."], ["Concevoir une captation hybride", "Un chat adossé à un formulaire complète progressivement les informations. Le client valide un résumé structuré avant la poursuite du parcours."], ["Conserver l’intervention humaine", "La négociation et les cas complexes restent du ressort des équipes. Les cas logistiques complexes bloquent le prix et déclenchent une escalade ; les demandes urgentes appellent un rappel humain."]], "steps": [["Qualifier", "Le dialogue complète les informations de transport et prépare l’attribution au commercial."], ["Valider", "Le client vérifie un résumé structuré de sa demande avant la suite."], ["Chiffrer", "Un calcul déterministe produit le devis des cas simples ; les cas complexes sont orientés vers un humain."]], "deliverables": ["Landing page", "Dashboard commercial", "Parcours conversationnel", "Calcul déterministe du devis", "Architecture cible", "Présentation du MVP"], "outcome": "Automatiser le répétitif. Préserver le conseil.", "outcomeText": "Le prototype de la semaine couvre une tranche du parcours de bout en bout. L’architecture présentée repose sur Next.js, AI SDK et Supabase, avec des outils déterministes pour le devis et les opérations métier. La profondeur du MVP reste limitée sur les fonctions périphériques : téléphonie et agenda sont simulés. Le traitement de 100 % des demandes sous 48 h est un objectif cible, pas un résultat mesuré.", "resourceNote": "Contenu issu de la présentation du groupe 23. Les chiffres décrivent le cas étudié et les objectifs du projet. Les deux liens donnent accès au site et au dashboard de démonstration.", "quote": "Digitaliser sans déshumaniser.", "axis": "L’agent décide.<br>Le code calcule.", "axisItems": [["Conversation & interface", "Captation · Qualification · Résumé validé"], ["Calcul & intervention humaine", "Prix déterministe · Escalade · Rappel"]], "coverCaption": "Diapositive d’ouverture originale · Présentation NeoTravel, groupe 23.", "links": [["Visiter le site NeoTravel", "Découvrir la landing page et l’entrée du parcours client.", "https://neotravel-app-fefd.vercel.app/", "external"], ["Explorer le dashboard", "Accéder à l’interface de démonstration destinée aux équipes.", "https://neotravel-app-fefd.vercel.app/dashboard", "external"], ["Télécharger la présentation", "Le contexte, les choix du MVP et l’architecture · PowerPoint · 11 diapositives.", "assets/neotravel-presentation.pptx", "download"]], "gallery": [["assets/neo-01.webp", "Le projet NeoTravel", "Présentation NeoTravel · Diapositive 1 / 11"], ["assets/neo-02.webp", "Le contexte métier", "Présentation NeoTravel · Diapositive 2 / 11"], ["assets/neo-03.webp", "Le problème de traitement", "Présentation NeoTravel · Diapositive 3 / 11"], ["assets/neo-04.webp", "Les priorités du MVP", "Présentation NeoTravel · Diapositive 4 / 11"], ["assets/neo-05.webp", "Le parcours cible", "Présentation NeoTravel · Diapositive 5 / 11"], ["assets/neo-06.webp", "Le calcul du devis", "Présentation NeoTravel · Diapositive 6 / 11"], ["assets/neo-07.webp", "L’architecture retenue", "Présentation NeoTravel · Diapositive 7 / 11"], ["assets/neo-08.webp", "Les garde-fous", "Présentation NeoTravel · Diapositive 8 / 11"], ["assets/neo-09.webp", "Le parcours de démonstration", "Présentation NeoTravel · Diapositive 9 / 11"], ["assets/neo-10.webp", "La roadmap et le MVP", "Présentation NeoTravel · Diapositive 10 / 11"], ["assets/neo-11.webp", "Les indicateurs à suivre", "Présentation NeoTravel · Diapositive 11 / 11"]], "projectFacts": [["Contexte", "≈ 60 leads / jour", "Volume cité dans la présentation"], ["Point de départ", "≈ 45 min / lead", "Traitement manuel du cas étudié"], ["Objectif", "100 % sous 48 h", "Cible du projet, non mesurée"]], "projectTeam": "Projet collectif · Équipe 23 : Ihsane Abdou, Kylian Baconnet, Paul Balcon et Alexis de Malet."};

// Project case studies and original mockups
PROJECTS["biodiv"]={"name": "Biodiv", "number": "03", "tone": "biodiv", "discipline": "Product design · UX/UI", "headline": "Des données écologiques.<br>Un export <em>sur mesure.</em>", "intro": "Une plateforme pour aider les écologues à réunir les données sur la faune et la flore, puis générer un CSV adapté à leur étude.", "context": "Comment transformer des données dispersées en un export pertinent pour une étude ?", "description": "Les études écologiques mobilisent des observations de faune et de flore réparties dans différents fichiers CSV. Biodiv propose de réunir les sources référencées dans un même parcours pour composer un jeu de données adapté à chaque étude. L’écologue sélectionne les sources, précise une période, des espèces et un périmètre géographique, puis génère son export. L’enjeu de conception est de rendre ce paramétrage compréhensible sans masquer la richesse des critères métier.", "focus": [["Choisir les sources", "Les sources sont présentées sous forme de cartes sélectionnables. L’utilisateur garde la maîtrise du périmètre documentaire de son export."], ["Affiner la recherche", "Période, espèces et localisation structurent les filtres. La maquette propose notamment région, département, commune et habitat."], ["Générer un CSV ciblé", "Une action finale explicite transforme les paramètres choisis en demande d’export. L’objectif est de réduire les manipulations répétitives entre fichiers."]], "steps": [["Sélectionner", "Choisir les sources de données pertinentes pour l’étude."], ["Paramétrer", "Définir la période, les espèces et le territoire recherchés."], ["Exporter", "Générer un CSV correspondant aux paramètres sélectionnés."]], "deliverables": ["Interface de sélection des sources", "Filtres temporels et géographiques", "Recherche et sélection d’espèces", "Parcours de génération CSV", "Composants de formulaire"], "outcome": "Rendre la préparation des données plus accessible.", "outcomeText": "Le formulaire est organisé en groupes distincts afin que l’utilisateur puisse relire ses choix avant de générer le CSV. Les espèces sélectionnées restent visibles et les filtres géographiques suivent une logique du général au particulier. Cette conception vise à limiter les manipulations manuelles entre fichiers et à faciliter la préparation des données pour l’analyse. Le mockup présente cette interface sous le nom BeeAPI.", "quote": "Donner aux écologues la maîtrise de leurs données, du choix des sources à l’export.", "axis": "Précision métier.<br>Simplicité du parcours.", "axisItems": [["Maîtriser le périmètre", "Sources sélectionnées · Période · Espèces"], ["Cibler le terrain", "Région · Département · Commune · Habitat"]], "meta": [["Contexte", "Sense4Data"], ["Public", "Écologues"], ["Format", "Plateforme web"], ["Sortie", "Export CSV personnalisé"]], "resourceNote": "Découvrez les interfaces dans le mockup original.", "coverCaption": "Mockup original · Biodiv"};
PROJECTS["nutrifast"]={"name": "Nutrifast", "number": "06", "tone": "nutrifast", "discipline": "Product design · UX/UI", "headline": "La semaine au menu.<br>La nutrition <em>en vue.</em>", "intro": "Une application pour générer ses menus de la semaine, préparer ses courses et suivre sa nutrition au même endroit.", "context": "Comment simplifier l’organisation des repas sans multiplier les outils ?", "description": "Décider des repas, vérifier les ingrédients à acheter et suivre ses apports sont des tâches liées, souvent réparties entre plusieurs supports. Nutrifast les rassemble dans une application : génération des menus de la semaine, calendrier des repas, liste de courses issue de la planification et suivi nutritionnel. L’objectif est de créer une continuité entre ce que l’on prévoit de manger, ce que l’on achète et ce que l’on suit au quotidien.", "focus": [["Planifier les repas", "Un calendrier organise les petits-déjeuners, déjeuners et dîners. Les fiches recettes mettent en avant temps de préparation et informations nutritionnelles."], ["Préparer les courses", "La liste est générée à partir des menus prévus. Les ingrédients sont regroupés par catégorie, avec leurs quantités, pour faciliter la préparation des achats."], ["Suivre sa nutrition", "Calories, protéines et hydratation sont présentées dans des indicateurs dédiés. Le profil réunit préférences, objectifs et recettes favorites."]], "steps": [["Planifier", "Générer ses menus et consulter les repas de la semaine."], ["Acheter", "Retrouver la liste de courses issue des menus choisis."], ["Suivre", "Consulter ses indicateurs de nutrition au quotidien."]], "deliverables": ["Accueil et suggestions de recettes", "Calendrier hebdomadaire", "Génération de menus", "Listes de courses par catégorie", "Suivi nutritionnel", "Profil et favoris"], "outcome": "Une continuité entre organisation et suivi.", "outcomeText": "Le calendrier permet de parcourir les repas jour par jour. Les listes regroupent les ingrédients par catégorie et affichent leurs quantités ; les cartes nutritionnelles distinguent les indicateurs par couleur. Le profil rassemble préférences, objectifs et recettes favorites. Le design cherche ainsi à rendre les informations faciles à retrouver, du choix du menu jusqu’aux courses.", "quote": "Faire le lien entre les repas de la semaine et les gestes du quotidien.", "axis": "Anticiper la semaine.<br>Suivre le quotidien.", "axisItems": [["Organisation", "Menus · Calendrier · Recettes · Courses"], ["Suivi personnel", "Calories · Protéines · Hydratation · Favoris"]], "meta": [["Format", "Application mobile"], ["Univers", "Alimentation"], ["Parcours", "Menus → courses → suivi"], ["Livrable", "Maquettes UX/UI"]], "resourceNote": "Découvrez les interfaces dans le mockup original.", "coverCaption": "Mockup original · Nutrifast"};
PROJECTS["oak"]={"name": "OAK", "number": "07", "tone": "oak", "discipline": "Product design · UX/UI", "headline": "Accompagner les talents.<br>Clarifier les <em>parcours.</em>", "intro": "Une plateforme RH qui réunit profil collaborateur, formations, opportunités et suivi des entretiens.", "context": "Comment rendre un parcours professionnel lisible dans une plateforme RH ?", "description": "OAK est une plateforme RH qui relie les informations des collaborateurs à leur évolution professionnelle. Elle rassemble profils, compétences, entretiens, formations et opportunités dans un espace commun. Réalisé pendant mon stage de Product Designer chez Sense4Data, le travail de conception vise à organiser ces contenus métier et à rendre les actions du quotidien plus faciles à identifier.", "focus": [["Structurer le profil collaborateur", "Rassembler les informations du collaborateur et rendre visible la progression de son profil pour créer un point de référence commun."], ["Accompagner les entretiens", "Organiser la création et les modèles d’entretien, ainsi que l’évaluation des compétences, pour soutenir les échanges autour de l’évolution professionnelle."], ["Donner des repères au quotidien", "Le tableau de bord associe humeur, formations, opportunités, candidatures et équipes. Les modules hiérarchisent les informations sans tout présenter au même niveau."]], "steps": [["Se situer", "Retrouver son profil et son tableau de bord."], ["Explorer", "Consulter les formations et les opportunités."], ["Progresser", "Suivre les entretiens et les compétences."]], "deliverables": ["Profils collaborateurs", "Progression de profil", "Création et modèles d’entretien", "Évaluation des compétences", "Accompagnement dans l’interface", "Tableau de bord RH"], "outcome": "Concevoir un espace RH lisible.", "outcomeText": "Mon travail couvre les fiches collaborateurs, la progression des profils, les entretiens et les systèmes d’évaluation des compétences. Des éléments d’accompagnement dans l’interface complètent le parcours. Le mockup illustre un tableau de bord modulaire avec une navigation latérale stable, pour passer d’une vue d’ensemble aux espaces métier.", "quote": "Organiser l’information RH autour des personnes et de leur évolution.", "axis": "Le quotidien du collaborateur.<br>Le suivi de son évolution.", "axisItems": [["Un espace personnel", "Profil · Humeur · Équipes · Candidatures"], ["Un parcours professionnel", "Compétences · Entretiens · Formations · Opportunités"]], "meta": [["Contexte", "Sense4Data"], ["Domaine", "Ressources humaines"], ["Format", "Plateforme web"], ["Rôle", "Product Designer"]], "resourceNote": "Découvrez les interfaces dans le mockup original.", "coverCaption": "Mockup original · OAK"};
PROJECTS["bye-buy-car"]={"name": "Bye Buy Car", "number": "08", "tone": "byebuycar", "discipline": "Product design · UX/UI", "headline": "Du véhicule<br>à la <em>rencontre.</em>", "intro": "Une application d’achat et de vente de véhicules d’occasion destinée aux garages, pour consulter les offres, publier son stock et entrer en contact.", "context": "Comment relier les besoins d’achat et de vente des garages ?", "description": "Bye Buy Car répond à un usage professionnel : permettre aux garages de proposer des véhicules d’occasion et de repérer des opportunités d’achat. Un même utilisateur peut être vendeur pour une annonce et acheteur pour une autre. L’expérience doit donc relier recherche, consultation des véhicules, gestion des publications et messagerie, tout en gardant les informations techniques et commerciales faciles à comparer.", "focus": [["Présenter le véhicule", "La fiche rassemble photos, prix et caractéristiques : marque, modèle, motorisation ou kilométrage. Cette hiérarchie aide le professionnel à examiner une offre avant de prendre contact."], ["Gérer les annonces du garage", "L’espace « Mes posts » centralise les véhicules publiés et l’accès à leur modification. Il distingue la gestion de son propre stock de la consultation du catalogue."], ["Faciliter la prise de contact", "L’action de messagerie est placée au niveau de la fiche véhicule. Les informations du garage donnent un contexte à l’échange entre professionnels."]], "steps": [["Rechercher", "Parcourir les véhicules disponibles et ouvrir une annonce correspondant au besoin du garage."], ["Examiner", "Consulter les photos, le prix, les caractéristiques et les informations du vendeur."], ["Contacter", "Engager l’échange autour du véhicule, ou retrouver ses propres annonces pour les gérer."]], "deliverables": ["Catalogue de véhicules", "Fiches détaillées", "Gestion des annonces", "Parcours d’accès", "Messagerie et profils"], "outcome": "Une expérience pensée pour les professionnels de l’occasion.", "outcomeText": "Le design donne une place centrale aux photos tout en conservant des fiches structurées pour les informations métier. La navigation mobile rend accessibles recherche, publication, annonces et messages. Le travail UX/UI réalisé chez Sense4Data comprend également les parcours d’accès et les profils, afin de relier la découverte de l’application à son usage professionnel.", "quote": "Faire de chaque annonce un point de départ pour un échange entre garages.", "axis": "Acheter et vendre.<br>Dans un même espace.", "axisItems": [["Côté acheteur", "Catalogue · Fiche véhicule · Contact"], ["Côté vendeur", "Publication · Annonces · Modification"]], "meta": [["Contexte", "Sense4Data"], ["Public", "Garages automobiles"], ["Marché", "Véhicules d’occasion · B2B"], ["Format", "Application mobile"]], "resourceNote": "Découvrez les interfaces dans le mockup original.", "coverCaption": "Mockup original · Bye Buy Car"};
PROJECTS["cartable-numerique"]={"name": "Le Cartable Numérique", "number": "09", "tone": "cartable", "discipline": "Product design · UX/UI", "headline": "Retrouver un cours.<br>Choisir comment <em>apprendre.</em>", "intro": "Une application éducative conçue pour une association au Sénégal qui fournit des tablettes aux élèves : un cartable numérique pour retrouver les ressources de leurs cours.", "context": "Comment réunir les ressources scolaires dans un cartable accessible sur tablette ?", "description": "L’association équipe les élèves de tablettes et souhaite y réunir les contenus nécessaires aux différents cours. Le Cartable Numérique transpose les repères d’un cartable scolaire dans une interface : des matières clairement identifiées, des ressources regroupées et un accès aux supports écrits, audio ou vidéo. L’enjeu est de permettre à l’élève de savoir où chercher et comment consulter son cours, dans un environnement cohérent.", "focus": [["Retrouver ses matières", "L’accueil organise les contenus par matière avec des repères colorés. Les derniers cours et documents partagés restent accessibles dès l’entrée."], ["Accéder aux ressources", "Les listes et la recherche aident à retrouver un cours. Le titre, l’auteur, le format et la durée donnent des repères avant de l’ouvrir."], ["Adapter la consultation au support", "Les pages de cours accueillent différents formats pédagogiques. Le mockup illustre notamment la lecture audio, ainsi que des états vides qui expliquent l’absence de contenu."]], "steps": [["Ouvrir son cartable", "Retrouver les matières et les derniers documents depuis l’accueil."], ["Choisir son cours", "Parcourir une matière ou rechercher une ressource précise."], ["Consulter", "Accéder au support écrit, audio ou vidéo associé au cours."]], "deliverables": ["Accueil par matière", "Organisation des ressources", "Recherche de cours", "Interfaces écrit, audio et vidéo", "États vides", "Palette et composants"], "outcome": "Un point d’accès commun aux ressources pédagogiques.", "outcomeText": "La conception relie accueil, matières, recherche et consultation des cours dans un parcours continu. La palette et les composants gardent les mêmes repères d’un écran à l’autre. Le travail réalisé chez Sense4Data porte sur la refonte des interfaces de cours et leur cohérence ; les mockups montrent les principes de navigation et de consultation prévus pour l’application.", "quote": "Un cartable qui rassemble les cours et aide chaque élève à s’y retrouver.", "axis": "Les repères de l’école.<br>Les possibilités du numérique.", "axisItems": [["S’organiser", "Matières · Derniers cours · Recherche"], ["Apprendre", "Documents · Audio · Vidéo · Lecture"]], "meta": [["Contexte", "Association au Sénégal"], ["Public", "Élèves équipés de tablettes"], ["Univers", "Éducation"], ["Réalisation", "UX/UI · Sense4Data"]], "resourceNote": "Découvrez les interfaces dans le mockup original.", "coverCaption": "Mockup original · Le Cartable Numérique"};
PROJECTS["village"]={"name": "Village", "number": "10", "tone": "evenements", "discipline": "UX/UI · Expérience athlète", "headline": "Vivre les Jeux.<br>Explorer le <em>Village.</em>", "intro": "Une application destinée aux athlètes des Jeux olympiques de Paris 2024 pour découvrir les lieux et services du village et faciliter leurs réservations sportives et culturelles.", "context": "Comment aider les athlètes à profiter de la vie du village entre les compétitions ?", "description": "Au-delà de leurs compétitions, les athlètes ont besoin de se repérer dans le village et d’organiser leurs moments disponibles. Village rassemble la découverte des lieux, les événements d’autres disciplines et les offres de divertissement, comme le cinéma. Le projet relie ainsi information pratique et réservation dans une même expérience mobile.", "focus": [["Se repérer dans le village", "Une carte répertorie les lieux et points d’intérêt. La recherche et les repères visuels permettent de trouver ce qui est disponible autour de soi."], ["Découvrir d’autres disciplines", "Une sélection d’événements organisée par sport donne accès aux rencontres. Les fiches mettent en avant les informations utiles et l’action de réservation."], ["Organiser ses loisirs", "L’expérience s’étend aux divertissements, notamment au cinéma. Les billets regroupent date, horaire et emplacement pour retrouver les informations nécessaires au moment de la sortie."]], "steps": [["Explorer", "Consulter la carte du village ou découvrir les événements et divertissements proposés."], ["Réserver", "Choisir une rencontre sportive ou une sortie et accéder à la réservation depuis sa fiche."], ["Retrouver son billet", "Consulter les informations pratiques de son ticket avant de se rendre à l’événement."]], "deliverables": ["Carte et points d’intérêt", "Catalogue d’événements", "Navigation par discipline", "Fiches et réservation", "Billets numériques"], "outcome": "De la découverte au billet, un parcours unifié.", "outcomeText": "Les maquettes relient quatre moments : se repérer sur une carte, choisir un événement, consulter sa fiche et retrouver son billet numérique. La navigation cherche à limiter la dispersion des informations et à faciliter l’organisation des temps libres des athlètes. Les visuels présentent une proposition de design pour ce contexte, sans présumer d’un déploiement officiel.", "quote": "Faciliter la vie des athlètes, sur le village et au-delà des compétitions.", "axis": "Une vie au village.<br>Des expériences à partager.", "axisItems": [["Au quotidien", "Carte · Lieux · Services · Recherche"], ["Pendant les temps libres", "Autres disciplines · Cinéma · Réservations · Billets"]], "meta": [["Public", "Athlètes"], ["Contexte", "Jeux de Paris 2024"], ["Format", "Application mobile"], ["Périmètre", "Village · Sports · Loisirs"]], "resourceNote": "Découvrez les interfaces dans le mockup original.", "coverCaption": "Mockup original · Événements & billetterie"};
