PROJECTS.releve={"name": "Relève", "number": "01", "tone": "releve", "discipline": "Projet digital · UX/UI · Développement web", "headline": "Du talent.<br>Du terrain. <em>Du concret.</em>", "intro": "J’ai conçu et développé Relève pour mettre en relation les entreprises du BTP et les intérimaires disponibles en Gironde. Développé sous le nom InteriMatch, ce projet rend la recherche de missions et de profils plus claire.", "meta": [["Format", "Plateforme web · POC"], ["Secteur", "Intérim BTP · Gironde"], ["Réalisation", "Paul Balcon"], ["Période", "Septembre 2026"]], "context": "Comment trouver le bon profil au bon moment ?", "description": "Un chantier impose des dates, des compétences et des contraintes de déplacement. J’ai conçu Relève pour relier ces besoins à des profils disponibles, puis accompagner la décision jusqu’au suivi de mission. La plateforme réunit recherche publique, espace candidat, espace recruteur et administration, avec une expérience propre à chaque rôle.", "focus": [["Un démarrage guidé", "Un onboarding en quatre étapes rend visible la progression du profil. Métier, compétences, mobilité et disponibilités structurent le parcours candidat ; activité, interlocuteur et coordonnées structurent celui de l’entreprise. Les étapes sont calculées à partir des informations réellement enregistrées."], ["Un matching explicable", "Trois critères conditionnent l’éligibilité : dates couvertes, compétences indispensables et rayon de déplacement. Le score additionne ensuite les compétences souhaitées (50 points), la proximité (30) et l’expérience (20). Chaque incompatibilité est expliquée ; l’expérience reste préférentielle, pas bloquante."], ["Prévoir les imprévus du terrain", "Le recruteur compare les candidats et peut constituer une réserve de trois profils. La mobilisation d’un remplaçant demande une confirmation et revérifie la compatibilité ainsi que les conflits de dates. Les candidatures disposent de statuts lisibles et certaines décisions peuvent être annulées avant le début de mission."], ["Accompagner les candidats", "Recherche filtrée, favoris et suivi des candidatures sont complétés par un espace de formation : huit modules d’initiation, leçons, quiz et progression sauvegardée. Ces modules ne délivrent pas de certification ni d’habilitation."], ["Centraliser les justificatifs", "Le candidat gère ses documents dans un espace privé, avec contrôle du format et de la taille, chiffrement et accès rattaché au compte. Une analyse optionnelle des certificats et permis peut être activée avec accord explicite ; elle ne modifie pas le score de matching et ne décide pas du recrutement."], ["Piloter et automatiser", "L’administration regroupe les missions urgentes, les profils, les documents et le suivi des envois. Les workflows n8n traitent les alertes de matching, les confirmations et les relances ; les statuts distinguent les fichiers déposés localement des messages remis au serveur email."]], "steps": [["Préparer", "Créer son compte et compléter un profil guidé : métier, savoir-faire, zone de déplacement et dates disponibles."], ["Trouver", "Rechercher une mission, consulter ses critères et comprendre les correspondances proposées."], ["Décider", "Candidater, comparer les profils ou constituer une réserve, avec confirmation avant les actions importantes."], ["Suivre", "Retrouver les statuts, notifications et documents ; gérer un remplacement si le besoin évolue."]], "axis": "Deux espaces.<br>Un même terrain.", "axisItems": [["Candidat", "Profil guidé · Recherche · Favoris · Candidatures · Formations · Justificatifs"], ["Recruteur", "Publication · Scores détaillés · Réserve · Affectation · Documents · Indicateurs"]], "quote": "Un matching expliqué et local.", "deliverables": ["Recherche publique et filtres", "Espaces candidat, recruteur et administration", "Onboarding en quatre étapes", "Matching déterministe et expliqué", "Réserves et remplacements", "Formations et quiz", "Documents privés et chiffrés", "Notifications et workflows n8n", "Données France Travail", "Motion design et démonstration"], "outcome": "Un produit pensé au-delà de la mise en relation.", "outcomeText": "Le prototype couvre la préparation du profil, la recherche, la sélection et le suivi des missions. Son architecture associe Next.js, React et TypeScript à SQLite pour les données métier, les sessions et les transactions. Redis sert de journal temporaire facultatif ; n8n traite les notifications à partir d’une file persistante. Le dépôt fournit aussi des tests métier et des scénarios navigateur. Relève reste un POC : les confirmations générées ne sont pas des contrats de travail, et la paie ainsi que les obligations d’employeur relèvent d’une ETT partenaire.", "projectTeam": "Projet conçu et réalisé par Paul Balcon.", "roleDetails": [["Chef de projet digital", "Définition du besoin, cadrage du périmètre et organisation du projet, de la première idée à la soutenance."], ["Product Design", "Conception des parcours par rôle, de l’onboarding et des interfaces : rendre les critères, les statuts et les actions compréhensibles."], ["Développement web", "Réalisation des espaces métier, du matching, des données et des automatisations, avec validation côté serveur et scénarios de test."]], "coverCaption": "Relève · Visuel extrait du motion design du projet.", "resourceNote": "Les fonctionnalités décrites s’appuient sur le code et la documentation du projet. Les démonstrations utilisent des comptes fictifs. L’actualisation France Travail, l’envoi email et l’analyse documentaire nécessitent leurs propres configurations ; ils n’ont pas été exécutés dans le cadre de cette présentation.", "links": [["Présentation de soutenance", "Le support complet du projet, consultable dans un nouvel onglet.", "assets/releve-soutenance.html", "external"]]};
const PROJECT_ORDER=["releve", "melo", "neotravel", "pikit", "nutrifast", "manach", "web", "oak", "biodiv", "cartable-numerique", "bye-buy-car", "kolok", "village"];
PROJECT_ORDER.forEach((id,index)=>{PROJECTS[id].number=String(index+1).padStart(2,'0');});
const home=document.querySelector('#home-view'),caseView=document.querySelector('#case-view');
let prerendered=!!caseView.querySelector('.case-page');const coverHTML={};document.querySelectorAll('.project').forEach(el=>{coverHTML[el.getAttribute('href').split('/').filter(Boolean).pop()]=el.querySelector('.project-visual').outerHTML;});
let activeProject=null;
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function mockupResources(p){return `<figure class="original-mockup"><a href="${asset(p.mockup)}" target="_blank" rel="noopener noreferrer" aria-label="Agrandir le mockup de ${esc(p.name)}"><img src="${asset(p.mockup)}" alt="Maquettes originales de ${esc(p.name)}" loading="lazy"></a><figcaption><span>Maquettes originales · ${esc(p.name)}</span><a class="text-action" href="${asset(p.mockup)}" target="_blank" rel="noopener noreferrer">Agrandir l’aperçu ↗</a></figcaption></figure>`;}
function figmaFrame(p){return `<iframe title="${p.figmaUrl?'Aperçu interactif Figma de '+esc(p.name):'Portfolio Figma de Paul Balcon'}" src="https://www.figma.com/embed?embed_host=share&url=${encodeURIComponent(p.figmaUrl||FIGMA)}" allowfullscreen loading="lazy"></iframe><p>Si l’aperçu ne s’affiche pas, utilisez « Ouvrir dans Figma ». L’accès dépend des autorisations du fichier.</p>`;}
function figmaResources(p){return `<div class="resource-panel"><div class="resource-icon">F</div><div><h3>${p.figmaUrl?esc(p.name)+', dans Figma':'Mon portfolio Figma'}</h3><p>${p.figmaUrl?'Explorez la maquette originale : zoomez, déplacez-vous et découvrez les écrans du projet.':'Lien original figurant dans le QR code de mon CV. Il ouvre le portfolio global, pas directement la maquette '+p.name+'.'}</p></div><a href="${p.figmaUrl||FIGMA}" target="_blank" rel="noopener noreferrer" class="action">Ouvrir dans Figma ↗</a></div><div class="figma-controls"><button class="text-action" data-embed aria-expanded="${!!p.figmaUrl}" aria-controls="figma-preview">${p.figmaUrl?'Masquer l’aperçu Figma ↑':'Afficher l’aperçu Figma ↓'}</button><p>L’aperçu nécessite une connexion internet et les droits d’accès au fichier.</p></div><div id="figma-preview" class="figma-slot ${p.figmaUrl?'project-figma':''}">${p.figmaUrl?figmaFrame(p):''}</div>`;}
function galleryFrame(p,n){const [src,title,caption]=p.gallery[n];return `<img src="${asset(src)}" alt="${esc(title)}" width="1400" height="788"><figcaption><strong>${title}</strong><span>${caption}</span></figcaption>`;}
function projectResources(p){return `<div class="project-links">${p.links.map(([title,desc,href,type])=>`<div class="resource-panel"><div class="resource-icon">${type==='download'?'↓':'↗'}</div><div><h3>${title}</h3><p>${desc}</p></div><a class="action" href="${asset(href)}" ${type==='download'?`download="${href.split('/').pop()}"`:'target="_blank" rel="noopener noreferrer"'}>${type==='download'?'Télécharger ↓':'Ouvrir ↗'}</a></div>`).join('')}</div>`;}
function projectQuickLinks(p){const links=[];if(p.liveUrl)links.push(['Ouvrir '+p.name,p.liveUrl,false]);if(p.links)p.links.forEach(([title,desc,url,type])=>links.push([title,url,type==='download']));if(p.figmaUrl)links.push(['Ouvrir la maquette Figma',p.figmaUrl,false]);return links.length?`<div class="project-quick-links" aria-label="Liens du projet">${links.map(([title,url,download])=>`<a class="action" href="${asset(url)}" ${download?'download':'target="_blank" rel="noopener noreferrer"'}>${esc(title)} ${download?'↓':'↗'}</a>`).join('')}${p.figmaUrl?'<button class="text-action" data-scroll="case-resources">Aperçu interactif Figma ↓</button>':''}</div>`:'';}
function hecPhotos(){const photos=[['melo-hec-pitch',1200,1600,'Présenter MELO','Présentation du projet MELO dans le cadre du certificat AI Entrepreneurship à HEC.'],['melo-hec-victoire',1200,1600,'Une victoire collective','L’équipe MELO réunie pour célébrer sa victoire à l’issue du programme.'],['melo-hec-equipe',1600,1200,'Défendre notre vision en équipe','Présentation des écrans de MELO et de l’expérience pensée pour les étudiants.']];return `<section class="case-section hec-moments" id="case-hec"><span class="eyebrow">HEC · AI ENTREPRENEURSHIP</span><h2>Du pitch<br>à la victoire.</h2><p class="case-body">Six semaines pour construire un projet de startup, puis le présenter devant un jury d’investisseurs. Ces moments retracent la présentation de MELO et notre victoire collective à l’issue du certificat.</p><div class="hec-photo-grid">${photos.map(([file,w,h,title,caption],i)=>`<figure class="hec-photo ${i===2?'hec-photo-wide':''}"><a href="${asset('assets/'+file+'.webp')}" target="_blank" rel="noopener noreferrer" aria-label="Agrandir : ${esc(title)}"><img src="${asset('assets/'+file+'.webp')}" width="${w}" height="${h}" loading="lazy" decoding="async" alt="${esc(caption)}"><span aria-hidden="true">↗</span></a><figcaption><h3>${title}</h3><p>${caption}</p></figcaption></figure>`).join('')}</div></section>`;}
function neotravelMedia(){return `<section class="case-section releve-media neotravel-intro-video" id="case-videos"><span class="eyebrow">LE PROJET EN VIDÉO</span><h2>NeoTravel en 32 secondes.</h2><figure><video controls playsinline preload="none" poster="/assets/neotravel-motion-poster.webp" aria-label="Vidéo de présentation de NeoTravel, 32 secondes"><source src="/assets/neotravel-motion.mp4" type="video/mp4"></video><figcaption><h3>Présentation de NeoTravel</h3><p>Un aperçu du projet en motion design.</p></figcaption></figure></section>`;}
function releveMedia(){return `<section class="case-section releve-media" id="case-videos"><span class="eyebrow">LE PROJET EN IMAGES</span><h2>De l’intention<br>à l’utilisation.</h2><figure><video controls playsinline preload="none" poster="/assets/releve-cover.webp" aria-label="Motion design Relève, 15 secondes"><source src="/assets/releve-motion.mp4" type="video/mp4"></video><figcaption><h3>Relève en 15 secondes</h3><p>Le motion design présente l’univers du projet : les talents, le terrain et le chantier.</p></figcaption></figure><figure><video controls playsinline preload="none" poster="/assets/releve-demo-poster.webp" aria-label="Démonstration de Relève, environ trois minutes"><source src="/assets/releve-demo.mp4" type="video/mp4"></video><figcaption><h3>Le produit en action</h3><p>Une démonstration des parcours entreprise et intérimaire : création d’une mission, matching, affectation et suivi.</p></figcaption></figure></section>`;}
function renderProject(id){const p=PROJECTS[id];if(!p){location.hash='projets';return;}activeProject=id;home.hidden=true;caseView.hidden=false;document.body.classList.add('is-case');document.title=p.name+' — '+p.discipline.split(' · ')[0]+' | Paul Balcon';const next=PROJECT_ORDER[(PROJECT_ORDER.indexOf(id)+1)%PROJECT_ORDER.length];if(prerendered)prerendered=false;else caseView.innerHTML=`<article class="case-page theme-${p.tone}"><div class="case-top"><a href="/#projets">← Tous les projets</a><span>ÉTUDE DE PROJET / ${p.number}</span><a href="/#contact">Discutons-en ↗</a></div><section class="case-hero"><div class="case-title-line"><span class="eyebrow">${p.discipline}</span><span class="case-index" aria-hidden="true">${p.number}</span></div><p class="case-name">${p.name}</p><h1>${p.headline}</h1><p class="case-intro">${p.intro}</p>${projectQuickLinks(p)}<div class="case-meta">${p.meta.map(([k,v])=>`<div><span>${k}</span><p>${v}</p></div>`).join('')}</div></section>${id==='neotravel'?neotravelMedia():''}<figure class="case-cover">${coverHTML[id]}<figcaption>${p.coverCaption||'Exploration visuelle pour le portfolio · Cette couverture n’est pas une capture du livrable original.'}</figcaption></figure><div class="case-layout"><aside class="case-nav" aria-label="Sommaire du projet"><span>DANS CE PROJET</span><button data-scroll="case-context">01 — Contexte</button><button data-scroll="case-focus">02 — Contributions</button><button data-scroll="case-experience">03 — Expérience</button><button data-scroll="case-delivery">04 — Livrables</button><button data-scroll="case-resources">05 — Aperçus & liens</button></aside><div class="case-content">${p.roleDetails?`<section class="project-role" aria-labelledby="project-role-title"><span class="eyebrow">MA CONTRIBUTION</span><h2 id="project-role-title">Mon rôle dans ce projet</h2><div>${p.roleDetails.map(([title,text])=>`<article><h3>${title}</h3><p>${text}</p></article>`).join('')}</div></section>`:''}<section id="case-context" class="case-section"><span class="eyebrow">01 / LE CONTEXTE</span><h2>${p.context}</h2><p class="case-body">${p.description}</p>${p.projectFacts?`<div class="project-facts">${p.projectFacts.map(([label,value,note])=>`<div><span>${label}</span><strong>${value}</strong><p>${note}</p></div>`).join('')}</div>`:''}</section>${id==='melo'?hecPhotos():''}${id==='releve'?releveMedia():''}<section id="case-focus" class="case-section"><span class="eyebrow">02 / ${id==='pikit'?'MES CONTRIBUTIONS':'LE PÉRIMÈTRE'}</span><h2>${id==='pikit'?'Penser le fond.<br>Concevoir la forme.':'Les points clés<br>du projet.'}</h2><div class="focus-list">${p.focus.map(([h,t],i)=>`<article><span>0${i+1}</span><div><h3>${h}</h3><p>${t}</p></div></article>`).join('')}</div></section><blockquote class="case-quote">${p.quote}</blockquote><section id="case-experience" class="case-section"><span class="eyebrow">03 / L’EXPÉRIENCE</span><h2>${p.axis}</h2><div class="axis-grid">${p.axisItems.map(([h,t])=>`<article><h3>${h}</h3><p>${t}</p></article>`).join('')}</div><div class="journey"><div class="journey-label">LECTURE DU ${['melo','pikit'].includes(id)?'PARCOURS ENVISAGÉ':'PROJET'}</div><div class="journey-buttons" role="group" aria-label="Étapes de l’expérience">${p.steps.map(([h],i)=>`<button data-step="${i}" aria-pressed="${i===0}"><span>0${i+1}</span>${h}</button>`).join('')}</div><div class="journey-detail" aria-live="polite"><span class="journey-number" aria-hidden="true">01</span><div><h3>${p.steps[0][0]}</h3><p>${p.steps[0][1]}</p></div></div><p class="journey-note">Présentation interactive du concept · Pas une démonstration du produit final.</p></div></section><section id="case-delivery" class="case-section"><span class="eyebrow">04 / LIVRABLES & PORTÉE</span><h2>${p.outcome}</h2><p class="case-body">${p.outcomeText}</p>${p.projectTeam?`<p class="project-team">${p.projectTeam}</p>`:''}<div class="deliverables">${p.deliverables.map((t,i)=>`<div><span>${String(i+1).padStart(2,'0')}</span>${t}</div>`).join('')}</div></section><section id="case-resources" class="case-section"><span class="eyebrow">05 / ALLER PLUS LOIN</span><h2>Les aperçus.<br>Les bons liens.</h2>${p.liveUrl?`<div class="resource-panel"><div class="resource-icon">↗</div><div><h3>Visiter le site</h3><p>Découvrir les réalisations et l’univers de ${esc(p.name)}.</p></div><a class="action" href="${p.liveUrl}" target="_blank" rel="noopener noreferrer">Ouvrir le site ↗</a></div>`:''}${p.mockup?mockupResources(p):''}${p.links?projectResources(p):(p.mockup&&!p.figmaUrl?'':figmaResources(p))}<p class="resource-note">${p.resourceNote}</p><a class="text-action" href="mailto:paul.balcon@orange.fr?subject=${encodeURIComponent('Échange autour du projet '+p.name)}">Échanger sur ce projet ↗</a></section></div></div><a class="next-project" href="/projets/${next}/"><span>CONTINUER L’EXPLORATION / ${PROJECTS[next].number}</span><div><h2>${PROJECTS[next].name}</h2><span>↗</span></div><p>${PROJECTS[next].discipline}</p></a></article>`;scrollTo({top:0,behavior:'instant'});const heading=caseView.querySelector('h1');heading.tabIndex=-1;heading.focus({preventScroll:true});}
function route(){
 const legacy=location.hash.match(/^#\/projet\/([a-z0-9-]+)$/);
 if(legacy){const id=legacy[1]==='evenements'?'village':legacy[1];if(PROJECTS[id]){location.replace('/projets/'+id+'/');return;}}
 const page=location.pathname.match(/^\/projets\/([a-z0-9-]+)\/?$/);
 if(page&&PROJECTS[page[1]]){renderProject(page[1]);return;}
 home.hidden=false;caseView.hidden=true;document.body.classList.remove('is-case');activeProject=null;
 const id=location.hash.slice(1);requestAnimationFrame(()=>{const el=id?document.getElementById(id):null;if(el){el.scrollIntoView({behavior:'instant'});el.tabIndex=-1;el.focus({preventScroll:true});}else if(!id)scrollTo({top:0,behavior:'instant'});});
}
addEventListener('hashchange',route);
caseView.addEventListener('click',e=>{const jump=e.target.closest('[data-scroll]');if(jump)document.getElementById(jump.dataset.scroll)?.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion:reduce)').matches?'instant':'smooth'});const step=e.target.closest('[data-step]');if(step&&activeProject){const n=+step.dataset.step,p=PROJECTS[activeProject];caseView.querySelectorAll('[data-step]').forEach(b=>b.setAttribute('aria-pressed',String(b===step)));caseView.querySelector('.journey-detail').innerHTML=`<span class="journey-number" aria-hidden="true">0${n+1}</span><div><h3>${p.steps[n][0]}</h3><p>${p.steps[n][1]}</p></div>`;}const embed=e.target.closest('[data-embed]');if(embed){const slot=caseView.querySelector('.figma-slot');const shown=!!slot.children.length;slot.innerHTML=shown?'':figmaFrame(PROJECTS[activeProject]);embed.setAttribute('aria-expanded',String(!shown));embed.textContent=shown?'Afficher l’aperçu Figma ↓':'Masquer l’aperçu Figma ↑';}});
const cvs={design:{name:'Product Designer',pdf:'assets/cv-product-designer.pdf',image:'assets/cv-design.webp',filename:'Paul-Balcon-Product-Designer.pdf'},project:{name:'Chef de projet digital & webmarketing',pdf:'assets/cv-chef-projet.pdf',image:'assets/cv-project.webp',filename:'Paul-Balcon-Chef-de-Projet.pdf'}};
const dialog=document.querySelector('#detail'),content=document.querySelector('#detail-content');let lastTrigger;
function asset(path){return window.PORTFOLIO_ASSETS?.[path]||(path.startsWith('assets/')||path.startsWith('certificates/')?'/'+path:path);}
document.querySelectorAll('[data-cv]').forEach(b=>b.addEventListener('click',()=>{lastTrigger=b;const cv=cvs[b.dataset.cv];document.getElementById('cv-title').textContent=cv.name;const a=document.getElementById('cv-download');a.href=asset(cv.pdf);a.download=cv.filename;content.innerHTML=`<img class="cv-full" src="${asset(cv.image)}" alt="CV original de Paul Balcon : ${esc(cv.name)}"><div class="cv-accessible"><h3>Paul Balcon — ${esc(cv.name)}</h3><p>Bordeaux, France · paul.balcon@orange.fr · +33 6 44 35 41 11</p><p>Expériences : Catalpa (juin–juillet 2025), Sense4Data (février–juillet 2024), Koloc (juin–juillet 2023). Formation : Epitech, MSc Business & Technology Manager (2022–aujourd’hui) ; HEC, AI Entrepreneurship Certificate (2026).</p><p>Consultez le PDF original pour le contenu complet.</p></div>`;dialog.showModal();dialog.scrollTop=0;document.body.classList.add('modal-open');}));
document.querySelector('.close').addEventListener('click',()=>dialog.close());dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close();}});dialog.addEventListener('close',()=>{document.body.classList.remove('modal-open');lastTrigger?.focus();});
document.querySelector('.copy-email')?.addEventListener('click',async()=>{const feedback=document.querySelector('.copy-feedback');try{if(navigator.clipboard&&window.isSecureContext){await navigator.clipboard.writeText('paul.balcon@orange.fr');}else{const t=document.createElement('textarea');t.value='paul.balcon@orange.fr';t.style.position='fixed';t.style.opacity='0';document.body.append(t);t.select();const ok=document.execCommand('copy');t.remove();if(!ok)throw Error('copy');}feedback.textContent='Adresse copiée !';}catch{feedback.textContent='Sélectionnez l’adresse pour la copier : paul.balcon@orange.fr';}});
const progress=document.querySelector('.progress');addEventListener('scroll',()=>{const max=document.documentElement.scrollHeight-innerHeight;progress.style.width=(max>0?scrollY/max*100:0)+'%';},{passive:true});
if('IntersectionObserver'in window&&!matchMedia('(prefers-reduced-motion: reduce)').matches){const observer=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting){e.target.classList.add('visible');observer.unobserve(e.target);}}),{threshold:.08});document.querySelectorAll('.section-head,.about-grid,.approach,.timeline,.cv-grid').forEach(el=>{el.classList.add('reveal');observer.observe(el);});}
if(window.PORTFOLIO_ASSETS){document.querySelectorAll('a[download]').forEach(a=>{const path=a.getAttribute('href');if(window.PORTFOLIO_ASSETS[path])a.href=window.PORTFOLIO_ASSETS[path];});}
route();

caseView.addEventListener('click',e=>{const b=e.target.closest('[data-gallery]');if(b&&activeProject){const p=PROJECTS[activeProject],g=caseView.querySelector('.deck-gallery'),n=Number(g.dataset.slide)+Number(b.dataset.gallery);if(n<0||n>=p.gallery.length)return;g.dataset.slide=n;g.querySelector('.deck-frame').innerHTML=galleryFrame(p,n);g.querySelector('.deck-count').textContent=`${n+1} / ${p.gallery.length}`;g.querySelector('[data-gallery="-1"]').disabled=n===0;g.querySelector('[data-gallery="1"]').disabled=n===p.gallery.length-1;}if(e.target.closest('[data-enlarge]')&&activeProject){const p=PROJECTS[activeProject],n=Number(caseView.querySelector('.deck-gallery').dataset.slide);lastTrigger=e.target.closest('[data-enlarge]');document.getElementById('cv-title').textContent=p.name+' · '+p.gallery[n][1];document.getElementById('cv-download').hidden=true;content.innerHTML=`<img class="cv-full" src="${asset(p.gallery[n][0])}" alt="${esc(p.gallery[n][1])}">`;dialog.showModal();dialog.scrollTop=0;document.body.classList.add('modal-open');}});
dialog.addEventListener('close',()=>document.getElementById('cv-download').hidden=false);

