// Motion is progressive enhancement: all content remains visible without it.
(() => {
  const reduced = matchMedia('(prefers-reduced-motion: reduce)');
  const seen = new WeakSet();
  const ease = 'cubic-bezier(.22,1,.36,1)';
  function enter(el, delay = 0, distance = 22) {
    if (reduced.matches || !el?.animate) return;
    el.animate([{opacity:0, transform:`translateY(${distance}px)`}, {opacity:1, transform:'translateY(0)'}], {duration:620, delay, easing:ease, fill:'backwards'});
  }
  const observer = 'IntersectionObserver' in window ? new IntersectionObserver(entries => {
    entries.forEach(({target,isIntersecting}) => {
      if (!isIntersecting) return;
      observer.unobserve(target);
      if (seen.has(target)) return;
      seen.add(target);
      enter(target,0,18);
    });
  }, {threshold:0, rootMargin:'0px 0px -24px 0px'}) : null;
  function observePage() {
    observer?.disconnect();
    const root = home.hidden ? caseView : home;
    if (home.hidden) enter(root.querySelector('.case-hero'),0,14);
    root.querySelectorAll('.section-head,.collaboration-heading,.collaboration-card,.project,.about-grid,.approach>div,.timeline article,.resume-card,.certificate-featured,.epitech-collection,.project-role,.case-section,.case-quote,.next-project').forEach(el => {
      if (!seen.has(el)) observer?.observe(el);
    });
  }
  if (!home.hidden) {
    ['.hero-intro','.profession','.hero-portrait','.hero-bottom'].forEach((selector,i)=>enter(document.querySelector(selector),i*75,16));
  }
  observePage();
  addEventListener('hashchange',observePage);
  document.addEventListener('click',e=>{
    if(reduced.matches)return;
    const trigger=e.target.closest('.action,.copy-email,.journey-buttons button,.close,.certificate-thumb,.resume-thumb');
    if(trigger?.animate) trigger.animate([{scale:'1'},{scale:'.97'},{scale:'1'}],{duration:220,easing:'ease-out'});
    if(e.target.closest('[data-step]')) enter(caseView.querySelector('.journey-detail'),0,8);
    if(e.target.closest('[data-gallery]')) enter(caseView.querySelector('.deck-frame'),0,8);
  });
  reduced.addEventListener('change',()=>{
    if(reduced.matches)document.getAnimations().forEach(animation=>animation.cancel());
  });
})();

// A rotating typographic headline, with explicit pause and offscreen suspension.
(() => {
 const title=document.querySelector('.role-current');
 if(!title)return;
 const reduced=matchMedia('(prefers-reduced-motion: reduce)');
 const roles=['Chef de projet<br><em>digital.</em>','Product<br><em>Designer.</em>','Développeur<br><em>web.</em>'];
 let index=0,cycles=0,paused=false,visible=true,busy=false,timer;
 function schedule(){clearTimeout(timer);if(!paused&&!reduced.matches&&visible&&!document.hidden)timer=setTimeout(advance,3800);}
 async function advance(){if(busy)return;busy=true;try{
  if(title.animate)await title.animate([{transform:'translateY(0) rotateX(0)',opacity:1},{transform:'translateY(-35%) rotateX(15deg)',opacity:0}],{duration:280,easing:'cubic-bezier(.55,0,1,.45)'}).finished;
  if(paused||reduced.matches)return;
  index=(index+1)%roles.length;if(index===0&&++cycles>=2)paused=true;title.innerHTML=roles[index];
  if(title.animate)await title.animate([{transform:'translateY(55%) rotateX(-16deg)',opacity:0},{transform:'translateY(0) rotateX(0)',opacity:1}],{duration:620,easing:'cubic-bezier(.22,1,.36,1)'}).finished;
 }catch{}finally{busy=false;schedule();}}
 reduced.addEventListener('change',()=>{if(reduced.matches){title.getAnimations?.().forEach(a=>a.cancel());index=0;title.innerHTML=roles[0];}schedule();});
 document.addEventListener('visibilitychange',schedule);
 if('IntersectionObserver'in window)new IntersectionObserver(entries=>{visible=entries[0].isIntersecting;schedule();}).observe(title);
 schedule();
 const fine=matchMedia('(hover:hover) and (pointer:fine)');
 document.querySelectorAll('.projects .project-visual').forEach(card=>card.addEventListener('pointermove',e=>{if(reduced.matches||!fine.matches)return;const rect=card.getBoundingClientRect();card.style.setProperty('--light-x',`${e.clientX-rect.left}px`);card.style.setProperty('--light-y',`${e.clientY-rect.top}px`);},{passive:true}));
})();
